//! Borrowed, buffered effect report transport; no source model or row clone.
use super::*;use serde::{Serialize,Serializer,ser::{SerializeSeq,SerializeStruct}};use dm_analysis::checker_effects::{Produced,EffectReportPhase};use std::io;
struct Hex(u128);impl Serialize for Hex{fn serialize<S:Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{let mut bytes=[b'0';32];let alphabet=b"0123456789abcdef";for(i,byte)in bytes.iter_mut().enumerate(){*byte=alphabet[((self.0>>((31-i)*4))&15)as usize];}serializer.serialize_str(std::str::from_utf8(&bytes).expect("fixed hex alphabet is ASCII"))}}
struct SourcePoint<'a>(&'a dm_tree::frontend::SourceNoteOrigin);impl Serialize for SourcePoint<'_>{fn serialize<S:Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{let mut value=serializer.serialize_struct("OriginalSourcePoint",3)?;value.serialize_field("file",self.0.path.as_ref())?;value.serialize_field("line",&self.0.line)?;value.serialize_field("column",&self.0.byte_column)?;value.end()}}
struct Notes<'a>(&'a [dm_analysis::checks::Note]);struct Note<'a>(&'a dm_analysis::checks::Note);impl Serialize for Note<'_>{fn serialize<S:Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{let mut value=serializer.serialize_struct("CheckerNote",2)?;value.serialize_field("message",&self.0.message)?;value.serialize_field("source",&self.0.source.as_ref().map(SourcePoint))?;value.end()}}impl Serialize for Notes<'_>{fn serialize<S:Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{let mut rows=serializer.serialize_seq(Some(self.0.len()))?;for note in self.0{rows.serialize_element(&Note(note))?;}rows.end()}}
struct Row<'a>{phase:&'static str,row:&'a Produced}impl Serialize for Row<'_>{fn serialize<S:Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{let row=self.row;let mut value=serializer.serialize_struct("OriginalEffectDiagnostic",9)?;value.serialize_field("phase",self.phase)?;value.serialize_field("registration_tag",&row.registration_tag)?;value.serialize_field("family",row.diagnostic.family)?;value.serialize_field("severity",super::super::named_policy::severity(row.severity))?;value.serialize_field("source",&SourcePoint(&row.origin))?;value.serialize_field("expanded_span",&[row.diagnostic.span.start,row.diagnostic.span.end])?;value.serialize_field("expression_span",&[row.diagnostic.expression_span.start,row.diagnostic.expression_span.end])?;value.serialize_field("message",&row.diagnostic.message)?;value.serialize_field("notes",&Notes(&row.diagnostic.notes))?;value.end()}}
struct Rows<'a>{pure:&'a [Produced],sleep:&'a [Produced]}impl Serialize for Rows<'_>{fn serialize<S:Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{let mut sequence=serializer.serialize_seq(None)?;for row in self.pure.iter().filter(|row|row.phase()==dm_analysis::checker_effects::ProducedPhase::BodyImmediate){sequence.serialize_element(&Row{phase:"body_immediate",row})?;}for row in self.sleep{sequence.serialize_element(&Row{phase:"must_not_sleep",row})?;}for row in self.pure.iter().filter(|row|row.phase()==dm_analysis::checker_effects::ProducedPhase::PurityGraph){sequence.serialize_element(&Row{phase:"must_be_pure",row})?;}sequence.end()}}
struct Wire<'a>{semantic:u128,source:u128,policy:u128,environment:&'a Path,body_count:usize,pure:&'a [Produced],sleep:&'a [Produced]}impl Serialize for Wire<'_>{fn serialize<S:Serializer>(&self,serializer:S)->Result<S::Ok,S::Error>{let mut value=serializer.serialize_struct("OriginalEffectReports",12)?;value.serialize_field("row","source_native_effect_reports")?;value.serialize_field("schema","dm-session-source-query-v1")?;value.serialize_field("semantic_revision",&Hex(self.semantic))?;value.serialize_field("source_revision",&Hex(self.source))?;value.serialize_field("policy_revision",&Hex(self.policy))?;value.serialize_field("environment",self.environment)?;value.serialize_field("body_count",&self.body_count)?;value.serialize_field("full_checker_parity",&false)?;value.serialize_field("effect_phase_order",&dm_analysis::checker_effects::EFFECT_PHASE_ORDER)?;value.serialize_field("target_group_order_contract",dm_analysis::checker_effects::TARGET_GROUP_ORDER_CONTRACT)?;value.serialize_field("diagnostics",&Rows{pure:self.pure,sleep:self.sleep})?;value.serialize_field("effect_report_only",&true)?;value.end()}}
impl SourceSnapshot{
 /// Actual body/SCC/report acquisition completes before any serializer/output
 /// write. The writer is additive and certifies only the named effect families;
 /// full-checker/client/default selection is deliberately a separate caller.
 pub(crate) fn write_native_effect_reports(&self,input:&Arc<dm_analysis::checker_effects::EffectInput>,width:usize,environment:&Path,explicit:Option<&Path>,tree:&dm_tree::SemanticTree,output:&mut impl io::Write)->io::Result<()>{self.with_effect_scope(input,environment,explicit,tree,|db,scope|{let pure=db.native_effect_source_report(input,scope,width,EffectReportPhase::Purity)?;let sleep=db.native_effect_source_report(input,scope,width,EffectReportPhase::Sleep)?;let wire=Wire{semantic:tree.identity().into(),source:self.source_revision,policy:self.policy_revision.ok_or_else(||io::Error::other("effect report policy frame is unavailable"))?,environment,body_count:input.archive().len(),pure:&pure,sleep:&sleep};db.write_effect_report_buffer(input,scope,width,&pure,&sleep,|writer|{serde_json::to_writer(&mut *writer,&wire).map_err(io::Error::from)?;writer.write_all(b"\n")},output)})}
}

